GLenum Wrap(ScreenWrap w){switch(w){case ScreenWrap::Repeat:return GL_REPEAT;case ScreenWrap::ClampEdge:return GL_CLAMP_TO_EDGE;case ScreenWrap::TransparentBorder:return GL_CLAMP_TO_BORDER;case ScreenWrap::LegacyClamp:return GL_CLAMP;}throw std::runtime_error("bad reference wrap");}
