 std::vector<uint8_t> Draw(const std::vector<Case>& cases,bool world){CGLSetCurrentContext(context);glViewport(0,0,W,H);glDisable(GL_DITHER);glDisable(GL_LIGHTING);glDisable(GL_FOG);glDisable(GL_SCISSOR_TEST);glDisable(GL_DEPTH_TEST);glDisable(GL_CULL_FACE);glClearColor(clear[0],clear[1],clear[2],clear[3]);glClear(GL_COLOR_BUFFER_BIT);glMatrixMode(GL_MODELVIEW);glLoadIdentity();glMatrixMode(GL_PROJECTION);glLoadIdentity();if(!world)glOrtho(0,W,0,H,-1,1);
