ScreenDrawList Geometry(const std::vector<Case>& cases,const std::string& wrong){ScreenDrawList list;for(size_t i=0;i<cases.size();++i){auto s=cases[i].state;auto uv=cases[i].uv;if(wrong=="omit-secondary")s.secondary={};if(wrong=="duplicate-uv")for(auto& v:uv){v[2]=v[0];v[3]=v[1];}if(wrong=="disable-incomplete"){if(s.texture&&s.texture->incomplete){s.texture.reset();s.material=ScreenMaterial::Solid;}if(s.secondary.texture&&s.secondary.texture->incomplete)s.secondary={};}if(wrong=="red-incomplete" || wrong=="black-incomplete"){auto red=std::make_shared<ScreenTexture>();red->width=red->height=1;red->bytesPerRow=4;red->bytes={uint8_t(wrong=="red-incomplete"?255:0),0,0,255};if(s.texture&&s.texture->incomplete)s.texture=red;if(s.secondary.texture&&s.secondary.texture->incomplete)s.secondary.texture=red;}
 const float x=float(i%COLS)*CELL,y=float(i/COLS)*CELL;std::array<ScreenVertex,4> vertices{{{x,y,0,tint},{x+CELL,y,0,tint},{x+CELL,y+CELL,0,tint},{x,y+CELL,0,tint}}};const std::array<uint32_t,6> ids{0,1,2,0,2,3};list.AppendTriangles(vertices,uv,ids,s);}return list;}
NativeWorldDrawFrame World(const std::vector<Case>& cases){NativeWorldDrawFrame f;uint64_t seq=0;for(size_t i=0;i<cases.size();++i){const float x=float(i%COLS)*CELL,y=float(i/COLS)*CELL;const std::array<std::array<float,2>,4> pos{{{x,y},{x+CELL,y},{x+CELL,y+CELL},{x,y+CELL}}};std::vector<NativeWorldDrawVertex> vertices;for(unsigned v:{0u,1u,2u,0u,2u,3u}){const float w=cases[i].perspective&&(v==1||v==2)?2:1;vertices.push_back({{(pos[v][0]*2/W-1)*w,(pos[v][1]*2/H-1)*w,0,w},tint,cases[i].uv[v]});}auto c=MakeNativeWorldDrawCommand(NativeWorldDrawStage::World,NativeDrawPrimitive::Triangles,vertices,cases[i].state,{});c.sequence=++seq;f.draws.push_back(std::move(c));}return f;}
std::vector<uint8_t> Render(ScreenGPU& images,WorldOverlayGPU& overlays,const ScreenDrawList& list,const NativeWorldDrawFrame* world){RuntimeLease lease;double ms=0;auto d=[MTLTextureDescriptor texture2DDescriptorWithPixelFormat:MTLPixelFormatRGBA8Unorm width:W height:H mipmapped:NO];d.storageMode=MTLStorageModeShared;d.usage=MTLTextureUsageRenderTarget;auto target=[lease.Device() newTextureWithDescriptor:d];Require(target!=nil,"oracle output allocation failed");lease.AddAllocation(target);ScreenDrawList empty;auto screen=images.Prepare(lease,{world?&empty:&list,W,H,{},{}},W,H,W,H,MTLPixelFormatRGBA8Unorm,true,ms);std::unique_ptr<PreparedWorldOverlayFrame> prepared;id<MTLTexture> depth=nil;if(world){auto dd=[MTLTextureDescriptor texture2DDescriptorWithPixelFormat:MTLPixelFormatDepth32Float width:W height:H mipmapped:NO];dd.storageMode=MTLStorageModePrivate;dd.usage=MTLTextureUsageRenderTarget;depth=[lease.Device() newTextureWithDescriptor:dd];Require(depth!=nil,"oracle depth allocation failed");lease.AddAllocation(depth);WorldCamera cam;cam.viewport={0,0,W,H};prepared=overlays.Prepare(lease,*world,images,screen.get(),cam,W,H,W,H,MTLPixelFormatRGBA8Unorm,MTLPixelFormatDepth32Float,MTLPixelFormatInvalid,true,ms);}lease.CommitResources();auto cmd=lease.Begin("Original fixed-function dual texture oracle");screen->EncodeDependencies(cmd);auto pass=[MTL4RenderPassDescriptor new];pass.colorAttachments[0].texture=target;pass.colorAttachments[0].loadAction=MTLLoadActionClear;pass.colorAttachments[0].storeAction=MTLStoreActionStore;pass.colorAttachments[0].clearColor=MTLClearColorMake(clear[0],clear[1],clear[2],clear[3]);pass.renderTargetWidth=W;pass.renderTargetHeight=H;if(world){pass.depthAttachment.texture=depth;pass.depthAttachment.loadAction=MTLLoadActionClear;pass.depthAttachment.storeAction=MTLStoreActionDontCare;pass.depthAttachment.clearDepth=1;}auto enc=[cmd renderCommandEncoderWithDescriptor:pass];Require(enc!=nil,"oracle encoder unavailable");if(prepared)for(size_t i=0;i<prepared->DrawCount();++i)prepared->EncodeDraw(i,enc);else screen->Encode(enc);[enc endEncoding];lease.SubmitAndWait(Clock::now(),0);screen->DidComplete();return lease.Readback(target,W,H,ms);}
NSDictionary* Compare(const std::vector<uint8_t>& a,const std::vector<uint8_t>& b,const std::vector<Case>& cases){uint64_t bad=0;unsigned maximum=0;NSMutableArray* rows=[NSMutableArray array];for(size_t ci=0;ci<cases.size();++ci){uint64_t n=0;unsigned max=0;for(size_t y=ci/COLS*CELL;y<(ci/COLS+1)*CELL;++y)for(size_t x=ci%COLS*CELL;x<(ci%COLS+1)*CELL;++x)for(size_t k=0;k<4;++k){size_t off=((H-1-y)*W+x)*4+k;const unsigned diff=unsigned(std::abs(int(a[off])-int(b[off])));max=std::max(max,diff);n+=diff>2;}[rows addObject:@{@"name":String(cases[ci].name),@"badChannels":@(n),@"maximumDifference":@(max)}];bad+=n;maximum=std::max(maximum,max);}return @{@"badChannels":@(bad),@"maximumDifference":@(maximum),@"channelChecks":@(cases.size()*CELL*CELL*4),@"cases":rows};}
}
int main(int argc,char** argv){@autoreleasepool{try{Require(argc>=2,"report path required");std::string wrong=argc>2?argv[2]:"";auto cases=Cases();if(argc>3){const std::string subset=argv[3];std::erase_if(cases,[&](const Case& c){return subset=="incomplete"?!c.name.starts_with("Incomplete"):subset=="units"?c.name!="Independent UV0 and UV1 MODULATE"&&c.name!="Texture0 disabled, texture1 enabled":false;});}Reference gl;auto expected=gl.Draw(cases,false);auto list=Geometry(cases,wrong);ScreenGPU images;WorldOverlayGPU overlay;auto actual=Render(images,overlay,list,nullptr);auto result=Compare(expected,actual,cases);NSMutableDictionary* report=[@{@"screen":result,@"negative":String(wrong),@"tolerance":@2,@"renders":@1}mutableCopy];uint64_t bad=[result[@"badChannels"] unsignedLongLongValue];if(wrong.empty()){auto f=World(cases);auto expectedWorld=gl.Draw(cases,true);auto actualWorld=Render(images,overlay,list,&f);auto wr=Compare(expectedWorld,actualWorld,cases);report[@"world"]=wr;report[@"renders"]=@2;bad+=[wr[@"badChannels"] unsignedLongLongValue];}report[@"status"]=bad?@"pixel_difference":@"passed";NSError* error=nil;auto json=[NSJSONSerialization dataWithJSONObject:report options:NSJSONWritingPrettyPrinted error:&error];Require(json&&!error&&[json writeToFile:String(argv[1]) atomically:YES],"report save failed");std::ofstream(std::string(argv[1])+".CGL.rgba",std::ios::binary).write(reinterpret_cast<const char*>(expected.data()),expected.size());std::ofstream(std::string(argv[1])+".Metal.rgba",std::ios::binary).write(reinterpret_cast<const char*>(actual.data()),actual.size());std::cout<<"Screen bad "<<[result[@"badChannels"] unsignedLongLongValue]<<", max "<<[result[@"maximumDifference"] unsignedIntValue]<<"\n";return bad?2:0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}}
